const { ethers } = require("hardhat");

async function main() {
    console.log("=== FINDING ACTUAL FUNCTION SELECTOR ===\n");

    // The transaction data from our last attempt
    const txData = "";

    const selector = txData.slice(0, 10);
    console.log("Function selector being called:", selector);

    // Check the deployed bytecode for this selector
    const EXCHANGE_ROUTER = "0x59b94d5B4686D59a4665d1679A8E27F71c544F40";
    const provider = ethers.provider;
    const bytecode = await provider.getCode(EXCHANGE_ROUTER);

    console.log("\n=== CHECKING IF SELECTOR EXISTS IN BYTECODE ===");
    if (bytecode.includes(selector.slice(2))) {
        console.log(`✅ Selector ${selector} IS in the bytecode`);
        console.log("The function exists but might be reverting");
    } else {
        console.log(`❌ Selector ${selector} is NOT in the bytecode`);
        console.log("The deployed contract doesn't have this function!");
    }
}

main()
    .then(() => process.exit(0))
    .catch((error) => {
        console.error(error);
        process.exit(1);
    });